tools.args:
{"command":"$ErrorActionPreference = 'Continue'
$candidates = @(
  "$env:LOCALAPPDATA\Yandex\YandexBrowser\User Data",
  "$env:LOCALAPPDATA\Yandex\Browser\User Data",
  "$env:APPDATA\Yandex\YandexBrowser\User Data"
)
foreach ($c in $candidates) {
  if (Test-Path $c) { Write-Output "FOUND: $c"; Get-ChildItem -Path $c -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '^(Default|Profile)' } | ForEach-Object { Write-Output ("  PROFILE: " + $_.FullName) } }
}","description":"Ищу каталог профилей Яндекс Браузера"}

{"command":"$ErrorActionPreference = 'Continue'
$root = "$env:LOCALAPPDATA\Yandex\YandexBrowser\User Data"
Get-ChildItem -Path $root -Directory | Where-Object { $_.Name -match '^(Default|Profile)' } | ForEach-Object {
  $sess = Join-Path $_.FullName 'Sessions'
  if (Test-Path $sess) {
    Get-ChildItem -Path $sess -File -Filter 'Session_*' | Sort-Object LastWriteTime -Descending | Select-Object -First 1 | ForEach-Object {
      Write-Output ("{0,-10} {1:yyyy-MM-dd HH:mm:ss} {2,10} bytes  {3}" -f $_.Directory.Parent.Name, $_.LastWriteTime, $_.Length, $_.FullName)
    }
  }
}
Write-Output "--- browser process ---"
Get-Process -Name 'browser' -ErrorAction SilentlyContinue | Select-Object -First 3 Id, StartTime, MainWindowTitle | Format-Table -AutoSize | Out-String","description":"Ищу самые свежие файлы сессии по профилям и проверяю процесс браузера"}

{"command":"$ErrorActionPreference = 'Continue'
$urls = Get-Content "$env:TEMP\mavis_tabs.txt" -Encoding UTF8
$noise = '(?i)/embed/|googlesyndication|doubleclick|googleads|/favicon|accounts\.youtube\.com|chrome-extension|^about:|^chrome://|^edge://|accounts\.google\.com|^https?://127\.0\.0\.1|^https?://localhost'
$clean = $urls | Where-Object { $_ -notmatch $noise } | ForEach-Object {
  # нормализация: убрать временные query-метки
  $u = $_
  $u = $u -replace '&sttick=\d+','' -replace '\?sttick=\d+','' -replace '&pp=[^&]*','' -replace '&t=\d+s',''
  $u
} | Where-Object { $_ -notmatch '\?&' -and $_ -notmatch '^\?t=' } | Select-Object -Unique
Write-Output ("clean: " + $clean.Count)
$clean | Set-Content "$env:TEMP\mavis_tabs_clean.txt" -Encoding UTF8
Write-Output "--- sqlite/python availability ---"
foreach ($c in 'sqlite3','python','python3','py') {
  $p = Get-Command $c -ErrorAction SilentlyContinue
  if ($p) { Write-Output ("FOUND: " + $c + " -> " + $p.Source) }
}","description":"Чищу список вкладок от шума и проверяю наличие sqlite3/python"}

{"command":"$ErrorActionPreference = 'Continue'
Get-CimInstance Win32_Process -Filter "Name='browser.exe'" | Select-Object -First 4 -ExpandProperty CommandLine
Write-Output "--- listening ports (9222/9223/9229/9333) ---"
foreach ($p in 9222,9223,9229,9333,9515) {
  $c = Test-NetConnection -ComputerName 127.0.0.1 -Port $p -InformationLevel Quiet -WarningAction SilentlyContinue
