{"command":"$ErrorActionPreference = 'Continue'
$cua = 'C:\Users\spay\AppData\Local\Programs\Cua\cua-driver\bin\cua-driver.exe'
$wins = @{ 460096 = 'w1_main'; 197338 = 'w2_main'; 71172340 = 'w3_youtube'; 3015764 = 'w4_market' }
foreach ($wid in $wins.Keys) {
  $name = $wins[$wid]
  $payload = @{ pid = 10104; window_id = $wid; include_accessibility_tree = $false; screenshot_out_file = "$env:TEMP\$name.png" } | ConvertTo-Json -Compress
  $r = $payload | & $cua call get_window_state 2>&1 | Out-String
  $ok = $r -match '"status"' 
  $f = Get-Item "$env:TEMP\$name.png" -ErrorAction SilentlyContinue
  Write-Output ("{0,-12} win={1,-9} file={2}" -f $name, $wid, $(if ($f) { "$($f.Length) bytes" } else { 'MISSING' }))
  if (-not $f) { Write-Output ($r.Substring(0, [Math]::Min(300, $r.Length))) }
}","description":"Снимаю скриншоты всех окон Яндекс Браузера"}
